@startuml

class Bank {}

class Branch {}

class Customer {
  +firstName : string
  +lastName : string
}

class Account {
  +accountNumber : int
  +currentBalance : double
}

class SavingsAccount extends Account {}

class CheckingAccount extends Account {
  +overdraftLimit : double
}

Bank "1" -- "*" Branch
Bank "1" -- "*" Customer
Customer "1" -- "1..5" Account : owns
Account "1" -- "1" Customer : owner

@enduml

